        /// Pending Updates store the changes pending from a previous update that will be applied to the Subscription upon success…
        public struct PendingUpdate: Codable, Hashable, Sendable {
            /// If the update is applied, determines the date of the first full invoice, and, for plans with `month` or `year` interva…
            public var billingCycleAnchor: Date?
            /// The pending subscription-level discount that will be applied when the pending update is applied.
            public var discount: Stripe.Shared.Discount?
            /// The discounts that will be applied to the subscription when the pending update is applied.
            @ExpandableCollection<Stripe.Shared.Discount> public var discounts: [String]?
            /// The point after which the changes reflected by this update will be discarded and no longer applied.
            public var expiresAt: Date?
            /// Set of key-value pairs that you can attach to an object.
            public var metadata: [String: String]?
            /// List of subscription items, each with an attached plan, that will be set if the update is applied.
            public var subscriptionItems: [Stripe.Billing.Subscription.Item]?
            /// Unix timestamp representing the end of the trial period the customer will get before being charged for the first time,…
            public var trialEnd: Date?
            /// Indicates if a plan's `trial_period_days` should be applied to the subscription.
            public var trialFromPlan: Bool?

            private enum CodingKeys: String, CodingKey {
                case billingCycleAnchor
                case discount
                case discounts
                case expiresAt
                case metadata
                case subscriptionItems
                case trialEnd
                case trialFromPlan
            }

            public init(
                billingCycleAnchor: Date? = nil,
                discount: Stripe.Shared.Discount? = nil,
                discounts: [String]? = nil,
                expiresAt: Date? = nil,
                metadata: [String: String]? = nil,
                subscriptionItems: [Stripe.Billing.Subscription.Item]? = nil,
                trialEnd: Date? = nil,
                trialFromPlan: Bool? = nil
            ) {
                self.billingCycleAnchor = billingCycleAnchor
                self.discount = discount
                self._discounts = ExpandableCollection(ids: discounts)
                self.expiresAt = expiresAt
                self.metadata = metadata
                self.subscriptionItems = subscriptionItems
                self.trialEnd = trialEnd
                self.trialFromPlan = trialFromPlan
            }
        }

